using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Topology.Measures;

internal sealed class L1RestrictionDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Literal indicator restriction",
        H("Literal indicator restriction"),
        Blocks(
            Describe.Lean(DescribeId.Create("restrict"),
                DeclarationHandle.Create("D5/S3/Topology/Measures/L1Restriction.restrict"),
                H("Literal indicator restriction"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Let Omega be an arbitrary type with an arbitrary measurable space, and let mu be an arbitrary measure. L1 means the real space Lp Real 1 mu. For every measurable set s with proof hs and every f in L1, restrict(s,hs,f) is MemLp.toLp of the actual function s.indicator(f). It uses the canonical strongly measurable representative of f."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("coe-restrict"),
                DeclarationHandle.Create("D5/S3/Topology/Measures/L1Restriction.coe_restrict"),
                H("Actual representative identity"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Let Omega be an arbitrary type with an arbitrary measurable space, and let mu be an arbitrary measure. L1 means the real space Lp Real 1 mu. For every measurable s and f in L1, the coerced representative of restrict(s,hs,f) equals s.indicator(f) almost everywhere. This is equality of L1 classes of literal restrictions."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("norm-restrict"),
                DeclarationHandle.Create("D5/S3/Topology/Measures/L1Restriction.norm_restrict"),
                H("Real norm of the literal restriction"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Let Omega be an arbitrary type with an arbitrary measurable space, and let mu be an arbitrary measure. L1 means the real space Lp Real 1 mu. For every measurable s and f in L1, the norm of restrict(s,hs,f) equals the real integral over s of the pointwise norm of f."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("enorm-restrict"),
                DeclarationHandle.Create("D5/S3/Topology/Measures/L1Restriction.enorm_restrict"),
                H("Extended norm of the literal restriction"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Let Omega be an arbitrary type with an arbitrary measurable space, and let mu be an arbitrary measure. L1 means the real space Lp Real 1 mu. For every measurable s and f in L1, the extended norm of restrict(s,hs,f) equals the nonnegative extended integral over s of the pointwise extended norm of f."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("add-compl"),
                DeclarationHandle.Create("D5/S3/Topology/Measures/L1Restriction.add_compl"),
                H("Exact complementary decomposition"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Let Omega be an arbitrary type with an arbitrary measurable space, and let mu be an arbitrary measure. L1 means the real space Lp Real 1 mu. For every measurable s and every f in L1, restrict(s,hs,f) plus restrict(s complement,hs.compl,f) equals f exactly in L1."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("norm-add-compl"),
                DeclarationHandle.Create("D5/S3/Topology/Measures/L1Restriction.norm_add_compl"),
                H("Exact norm additivity"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Let Omega be an arbitrary type with an arbitrary measurable space, and let mu be an arbitrary measure. L1 means the real space Lp Real 1 mu. For every measurable s and f in real L1, the sum of the norms of its literal restrictions to s and its complement equals the norm of f. Signed inputs are allowed."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("norm-le"),
                DeclarationHandle.Create("D5/S3/Topology/Measures/L1Restriction.norm_le"),
                H("Restriction decreases the norm"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Let Omega be an arbitrary type with an arbitrary measurable space, and let mu be an arbitrary measure. L1 means the real space Lp Real 1 mu. For every measurable s and f in L1, the norm of restrict(s,hs,f) is at most the norm of f."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("norm-mono"),
                DeclarationHandle.Create("D5/S3/Topology/Measures/L1Restriction.norm_mono"),
                H("Norm monotonicity in the carrier"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Let Omega be an arbitrary type with an arbitrary measurable space, and let mu be an arbitrary measure. L1 means the real space Lp Real 1 mu. For all measurable s and t with s contained in t and every f in L1, the norm of the literal restriction to s is at most the norm of the restriction to t."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("tailset"),
                DeclarationHandle.Create("D5/S3/Topology/Measures/L1Restriction.tailSet"),
                H("Actual measurable hard-tail carrier"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Let Omega be an arbitrary type with an arbitrary measurable space, and let mu be an arbitrary measure. L1 means the real space Lp Real 1 mu. For every natural k and f in L1, tailSet(k,f) is exactly the set of x with the real cast of k at most the pointwise norm of the canonical representative of f."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("measurable-tailset"),
                DeclarationHandle.Create("D5/S3/Topology/Measures/L1Restriction.measurable_tailSet"),
                H("Measurability in the original sigma algebra"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Let Omega be an arbitrary type with an arbitrary measurable space, and let mu be an arbitrary measure. L1 means the real space Lp Real 1 mu. For every natural k and f in L1, tailSet(k,f) is measurable in the original sigma algebra. No completion is introduced."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("tailnorm"),
                DeclarationHandle.Create("D5/S3/Topology/Measures/L1Restriction.tailNorm"),
                H("Real hard-tail mass"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Let Omega be an arbitrary type with an arbitrary measurable space, and let mu be an arbitrary measure. L1 means the real space Lp Real 1 mu. For every natural k and f in L1, tailNorm(k,f) is the norm of the literal restriction of f to tailSet(k,f)."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("tailnorm-antitone"),
                DeclarationHandle.Create("D5/S3/Topology/Measures/L1Restriction.tailNorm_antitone"),
                H("Hard-tail masses decrease"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Let Omega be an arbitrary type with an arbitrary measurable space, and let mu be an arbitrary measure. L1 means the real space Lp Real 1 mu. For every f in L1, the function from natural k to tailNorm(k,f) is antitone."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("tailnorm-compl"),
                DeclarationHandle.Create("D5/S3/Topology/Measures/L1Restriction.tailNorm_compl"),
                H("Exact nested-tail subtraction"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Let Omega be an arbitrary type with an arbitrary measurable space, and let mu be an arbitrary measure. L1 means the real space Lp Real 1 mu. For every f in L1 and natural thresholds 0 < k <= K, the k-tail mass of the literal restriction of f to the complement of tailSet(K,f) equals tailNorm(k,f) minus tailNorm(K,f). The positivity of k excludes zero values from the test tail. All integrals are finite before real subtraction."))), DescribeRole.Theorem))));
}
